 JSONArray read()throws Exception{JSONArray packets=new JSONArray();for(String name:list()){String tag=versions.get(name);JSONObject packet=cache.get(name);if(packet==null||!tag.equals(cachedTags.get(name))){try(Response r=request(name,"GET",null,Map.of())){check(r,200);try{packet=new JSONObject(text(r));}catch(JSONException e){throw new IOException("云端文件损坏，已保留本机记录");}validatePacket(packet);String serverTag=r.header("ETag");cachedTags.put(name,serverTag==null?tag:serverTag);cache.put(name,packet);}}packets.put(new JSONObject(packet.toString()));}cache.keySet().retainAll(versions.keySet());return packets;}
 static void validatePacket(JSONObject packet)throws Exception{if(packet.optInt("version")!=1||!(packet.opt("entries") instanceof JSONArray)||packet.getJSONArray("entries").length()>200000)throw new IOException("云端记录格式不兼容");JSONArray entries=packet.getJSONArray("entries");Set<String> seen=new HashSet<>();for(int i=0;i<entries.length();i++){JSONObject e=entries.getJSONObject(i);String g=e.getString("group"),id=e.getString("id");if(!Set.of("profile","tasks","sessions","thoughts","courseHabits","events","focusPresets").contains(g)||id.length()>100||!seen.add(g+":"+id)||!(e.opt("clock") instanceof JSONObject)||e.getJSONObject("clock").optLong("time",-1)<0||e.getJSONObject("clock").optString("device").isEmpty())throw new IOException("云端记录校验失败");if("profile".equals(g)&&!Set.of("name","motto","goal","duration","breakMinutes","sound").contains(id))throw new IOException("偏好格式错误");if(!"profile".equals(g)&&!e.isNull("value")&&!id.equals(e.getJSONObject("value").optString("id")))throw new IOException("记录标识不一致");}}
